package com.docuflow.dto;
import com.docuflow.entity.*; import jakarta.validation.constraints.*; import java.time.Instant; import java.util.*;
public final class DocumentDtos { private DocumentDtos(){} public record CreateRequest(@NotBlank @Size(max=180) String title,@NotEmpty List<Long> reviewerIds){} public record DecisionRequest(@NotNull ApprovalDecision decision){} public record CommentRequest(@NotBlank @Size(max=2000) String content){} public record DocumentResponse(Long id,String title,String originalFileName,long fileSize,DocumentStatus status,String owner,Instant createdAt,List<Reviewer> reviewers){} public record Reviewer(Long id,String name,ApprovalDecision decision){} public record CommentResponse(String author,String content,Instant createdAt){} public record ActivityResponse(String actor,String action,String detail,Instant createdAt){} }
